typedef struct { bool (*fn)(const void *, const void *); const void *ctx; } spec;

static bool overdue(const void *candidate, const void *ctx) {
    const invoice *inv = candidate;
    return days_past_due(inv) >= *(const int *)ctx;
}

bool spec_all(const spec *parts, size_t n, const void *candidate) {
    for (size_t i = 0; i < n; i++)
        if (!parts[i].fn(candidate, parts[i].ctx)) return false;  /* AND, short-circuit */
    return true;
}
